. /srv/work/s3-infra/s3/lib.sh; s3_release new
for t in s3sig10 s3sig60; do db=lab_$t; echo "$t: ledger rows(sig) $(PGDATABASE=$db psql_target pg16 -Atc "select count(*) from exponetdb.schema_migrations where name='long-sleep'") tables=[$(PGDATABASE=$db psql_target pg16 -Atc "select coalesce(string_agg(relname, ','), '-') from pg_class where relnamespace='public'::regnamespace and relkind='r'")] active sessions in pg_sleep=$(PGDATABASE=$db psql_target pg16 -Atc "select count(*) from pg_stat_activity where query like '%pg_sleep(60)%' and pid<>pg_backend_pid()") nextval=$(PGDATABASE=$db psql_target pg16 -Atc "select last_value from public.exec_seq")"; done
echo "operations of both: $(ctl_sql "select string_agg(operation_id||':'||state, ' ') from operations.operations where operation_id in ('op_01M64MEVZP4FP861E2H34V0WWK','op_01M64MGRXFCPPAK0F8K3ZT6GV0')")"
echo "worker heartbeat rows (stopped_at null = counted live?): "; ctl_sql "select process_id, stopped_at is null as not_stopped, now()-heartbeat_at as age from control.process_heartbeats where role='worker' order by started_at"
